async function folio(db:any,kind:string){if(!(kind in prefixes))return undefined;const year=new Intl.DateTimeFormat('en',{timeZone:'America/Mexico_City',year:'numeric'}).format(new Date());const key=kind+':'+year;const seq=await db.prepare('INSERT INTO sequences(key,value) VALUES(?,1) ON CONFLICT(key) DO UPDATE SET value=value+1 RETURNING value').bind(key).first();return `RP-${prefixes[kind]?prefixes[kind]+'-':''}${year}-${String(seq.value).padStart(5,'0')}`;}
const fail=(error:string,status=400)=>Response.json({error},{status});
